mapper.select:
select from ma_prompt_template
prompt_key = #{promptKey}
order by prompt_key asc, version desc

select distinct project_id from ma_invocation_log
project_id is not null and btrim(project_id) <> '' and created_at >= #{startTime} and created_at < #{endTime}
order by project_id asc

select distinct actor_service from ma_invocation_log
actor_service is not null and btrim(actor_service) <> '' and created_at >= #{startTime} and created_at < #{endTime}
order by actor_service asc
